contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        bool depositOk;
        c.sendMoney(address(this), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { depositOk = false; } else { depositOk = true; }
        require(depositOk);

        bool reverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted = true; } else { reverted = false; }

        assert(!reverted && address(c).balance == 0);
    }

    receive() external payable {}
}

